const input = $input.first().json;

/**
 * Find the first available value using several possible field names.
 *
 * Different n8n versions may use either the visible form label
 * or a configured internal field name.
 */
function getValue(...possibleNames) {
  for (const name of possibleNames) {
    const value = input[name];

    if (value !== undefined && value !== null) {
      return String(value).trim();
    }
  }

  return '';
}

/**
 * Clean short, single-line values.
 */
function cleanSingleLine(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Clean longer textarea values while keeping useful line breaks.
 */
function cleanMultiline(value) {
  return String(value ?? '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Create a safe code-friendly version of a name.
 *
 * Example:
 * "LumaDesk Technologies" becomes "LUMADESK-TECHNOLOGIES"
 */
function makeSlug(value) {
  return String(value)
    .normalize('NFKD')
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/[\s_]+/g, '-')
    .replace(/-+/g, '-')
    .toUpperCase();
}

/**
 * Small deterministic hash.
 *
 * This is not for password security.
 * It is only used to produce a consistent client reference.
 */
function simpleHash(value) {
  let hash = 2166136261;

  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return (hash >>> 0)
    .toString(36)
    .toUpperCase()
    .padStart(7, '0')
    .slice(0, 7);
}

/**
 * Add https:// when the client entered a domain without a protocol.
 */
function normalizeWebsite(value) {
  const cleaned = cleanSingleLine(value);

  if (!cleaned) {
    return '';
  }

  const withProtocol = /^https?:\/\//i.test(cleaned)
    ? cleaned
    : `https://${cleaned}`;

  const websitePattern =
    /^https?:\/\/[a-z0-9.-]+\.[a-z]{2,}(?::\d{1,5})?(?:[/?#][^\s]*)?$/i;

  if (!websitePattern.test(withProtocol)) {
    throw new Error(
      'Website must be a valid web address, such as https://example.com.'
    );
  }

  return withProtocol.replace(/\/+$/, '');
}

const clientName = cleanSingleLine(
  getValue('Client Name', 'client_name')
);

const companyName = cleanSingleLine(
  getValue('Company Name', 'company_name')
);

const clientEmail = cleanSingleLine(
  getValue('Client Email', 'client_email', 'email')
).toLowerCase();

const rawWebsite = getValue('Website', 'website');

const productService = cleanMultiline(
  getValue('Product or Service', 'product_service')
);

const targetAudience = cleanMultiline(
  getValue('Target Audience', 'target_audience')
);

const mainCustomerProblem = cleanMultiline(
  getValue('Main Customer Problem', 'main_customer_problem')
);

const offer = cleanMultiline(
  getValue('Offer', 'offer')
);

const campaignObjective = cleanSingleLine(
  getValue('Campaign Objective', 'campaign_objective')
);

const brandTone = cleanSingleLine(
  getValue('Brand Tone', 'brand_tone')
);

const callToAction = cleanSingleLine(
  getValue('Call to Action', 'call_to_action')
);

const competitorExamples = cleanMultiline(
  getValue('Competitor Examples', 'competitor_examples')
);

const additionalNotes = cleanMultiline(
  getValue('Additional Notes', 'additional_notes')
);

const submittedAt =
  getValue('submittedAt', 'submitted_at') ||
  new Date().toISOString();

/**
 * Server-side validation.
 *
 * Form-required fields improve the user experience, but a real system
 * should still validate the data after it reaches the workflow.
 */
const validationErrors = [];

const requiredValues = {
  'Client Name': clientName,
  'Company Name': companyName,
  'Client Email': clientEmail,
  'Product or Service': productService,
  'Target Audience': targetAudience,
  'Main Customer Problem': mainCustomerProblem,
  Offer: offer,
  'Campaign Objective': campaignObjective,
  'Brand Tone': brandTone,
  'Call to Action': callToAction,
};

for (const [label, value] of Object.entries(requiredValues)) {
  if (!value) {
    validationErrors.push(`${label} is required.`);
  }
}

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (clientEmail && !emailPattern.test(clientEmail)) {
  validationErrors.push('Client Email is not a valid email address.');
}

const allowedObjectives = [
  'Lead Generation',
  'Sales',
  'Website Traffic',
  'Brand Awareness',
];

if (
  campaignObjective &&
  !allowedObjectives.includes(campaignObjective)
) {
  validationErrors.push('Campaign Objective is not supported.');
}

const allowedBrandTones = [
  'Professional',
  'Friendly',
  'Energetic',
  'Simple',
  'Premium',
];

if (brandTone && !allowedBrandTones.includes(brandTone)) {
  validationErrors.push('Brand Tone is not supported.');
}

/**
 * Limit text sizes so a form submission cannot send an unexpectedly
 * huge amount of information into the database or AI model.
 */
const lengthLimits = [
  ['Client Name', clientName, 150],
  ['Company Name', companyName, 150],
  ['Client Email', clientEmail, 255],
  ['Product or Service', productService, 5000],
  ['Target Audience', targetAudience, 5000],
  ['Main Customer Problem', mainCustomerProblem, 5000],
  ['Offer', offer, 3000],
  ['Call to Action', callToAction, 150],
  ['Competitor Examples', competitorExamples, 5000],
  ['Additional Notes', additionalNotes, 5000],
];

for (const [label, value, maximum] of lengthLimits) {
  if (value.length > maximum) {
    validationErrors.push(
      `${label} exceeds the ${maximum}-character limit.`
    );
  }
}

let website = '';

if (rawWebsite) {
  try {
    website = normalizeWebsite(rawWebsite);
  } catch (error) {
    validationErrors.push(error.message);
  }
}

if (validationErrors.length > 0) {
  throw new Error(
    `Campaign brief validation failed:\n- ${validationErrors.join('\n- ')}`
  );
}

/**
 * The same company and email will produce the same client code.
 *
 * That allows us to update an existing client instead of creating
 * another client row every time they submit a new campaign.
 */
const clientIdentity = `${companyName.toLowerCase()}|${clientEmail}`;

const companySlug =
  makeSlug(companyName).slice(0, 22) || 'CLIENT';

const clientCode = `CL-${companySlug}-${simpleHash(clientIdentity)}`;

/**
 * The campaign code is readable by humans and unique enough for
 * the portfolio workflow.
 */
const now = new Date();

const datePart = now
  .toISOString()
  .replace(/\D/g, '')
  .slice(0, 14);

const randomPart = Math.random()
  .toString(36)
  .slice(2, 7)
  .toUpperCase()
  .padEnd(5, '0');

const campaignCode = `CMP-${datePart}-${randomPart}`;

/**
 * Store the full original business brief as JSON.
 *
 * PostgreSQL columns keep the most commonly searched fields, while
 * this JSON object preserves the complete brief.
 */
const brief = {
  client: {
    name: clientName,
    company_name: companyName,
    email: clientEmail,
    website,
  },
  campaign: {
    product_service: productService,
    target_audience: targetAudience,
    main_customer_problem: mainCustomerProblem,
    offer,
    objective: campaignObjective,
    brand_tone: brandTone,
    call_to_action: callToAction,
    competitor_examples: competitorExamples,
    additional_notes: additionalNotes,
  },
  submission: {
    submitted_at: submittedAt,
    form_version: '1.0.0',
  },
};

/**
 * This value creates a repeatable fingerprint for one form submission.
 *
 * Retrying the same saved execution will use the same submittedAt and
 * the same data, allowing PostgreSQL to identify it as the same
 * submission rather than creating a duplicate campaign.
 */
const idempotencyMaterial = JSON.stringify({
  submitted_at: submittedAt,
  client_email: clientEmail,
  company_name: companyName,
  product_service: productService,
  target_audience: targetAudience,
  offer,
  campaign_objective: campaignObjective,
});

/**
 * One object containing everything needed by PostgreSQL.
 */
const dbPayload = {
  client_code: clientCode,
  client_name: clientName,
  company_name: companyName,
  client_email: clientEmail,
  website,

  campaign_code: campaignCode,
  product_service: productService,
  target_audience: targetAudience,
  offer,
  campaign_objective: campaignObjective,
  brand_tone: brandTone,

  brief,
  idempotency_material: idempotencyMaterial,
};

return [
  {
    json: {
      client_code: clientCode,
      campaign_code: campaignCode,
      client_name: clientName,
      company_name: companyName,
      client_email: clientEmail,
      website,
      product_service: productService,
      target_audience: targetAudience,
      main_customer_problem: mainCustomerProblem,
      offer,
      campaign_objective: campaignObjective,
      brand_tone: brandTone,
      call_to_action: callToAction,
      competitor_examples: competitorExamples,
      additional_notes: additionalNotes,
      submitted_at: submittedAt,
      brief,
      db_payload: dbPayload,
      status: 'validated',
    },
  },
];
